  const source = inputs && typeof inputs === "object" ? inputs : {};
  const ROOT_FIELDS = [
    "schema_version",
    "generation_status",
    "case_summary",
    "question_count",
    "difficulty",
    "questions",
    "missing_information",
    "risk_message"
  ];
